return-response.set-body:
@{
                var jwt = (Jwt)context.Variables["caller-jwt"];
                var result = new JObject();
                foreach (var name in new[] { "oid", "tid", "upn", "preferred_username", "email", "name", "scp", "azp", "idtyp", "ver" }) {
                    result[name] = jwt.Claims.GetValueOrDefault(name, "");
                }
                result["aud"] = string.Join(",", jwt.Audiences);
                return result.ToString();
            }
